def flatten(arr):
    flattened_list = []
    for item in arr:
        if isinstance(item, list):
            # Recursively flatten the sublist and append its elements to the main list
            flattened_list.extend(flatten(item))
        else:
            # Append the current item directly to the main list
            flattened_list.append(item)
    return flattened_list
